from collections import deque,defaultdict
R,C=len(grid),len(grid[0])
seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  col=grid[r][c]
  if col==6 or (r,c) in seen: continue
  q=[(r,c)];seen.add((r,c)); cells=[]
  while q:
   x,y=q.pop();cells.append((x,y))
   for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
    z=(x+dx,y+dy)
    if 0<=z[0]<R and 0<=z[1]<C and z not in seen and grid[z[0]][z[1]]==col:
     seen.add(z);q.append(z)
  comps.append((col,cells))
def norm(cells):
 r0=min(x for x,y in cells);c0=min(y for x,y in cells)
 return frozenset((x-r0,y-c0) for x,y in cells)
for i,(col,cells) in enumerate(comps):
 rs=[x for x,y in cells];cs=[y for x,y in cells]
 print(i,col,len(cells),(min(rs),min(cs),max(rs),max(cs)), sorted(cells) if len(cells)<8 else '')

